class Node:
    def __init__(self, val):
        self.val, self.next = val, None

def find_middle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow.val

head = Node(1)
cur = head
for v in [2, 3, 4, 5]:
    cur.next = Node(v)
    cur = cur.next
